impl RustType {
    fn base_token(&self) -> TokenStream {
        match self {
            Self::Bool => quote!(bool),
            Self::U8 => quote!(u8),
            Self::I8 => quote!(i8),
            Self::I16 => quote!(i16),
            Self::I32 => quote!(i32),
            Self::I64 => quote!(i64),
            Self::F32 => quote!(f32),
            Self::F64 => quote!(f64),
            Self::String => quote!(String),
            Self::Bytes => quote!(Vec<u8>),
            Self::NamedObjectSchema(name) | Self::NamedEnumSchema(name) => {
                let ident = format_ident!("{}", name.as_pascal_case());
                quote!(#ident)
            }
            Self::UnnamedObjectSchema(unnamed) => {
                let ident = format_ident!("{}", unnamed.name());
                quote!(#ident)
            }
        }
